/* eslint-disable no-undef */
import { Component, Element, h, Host } from '@stencil/core';

/**
 *
 */
@Component({
  tag: 'groupui-stepper-vertical',
  styleUrl: 'stepper-vertical.scss',
  shadow: true,
})
export class StepperVertical {
  @Element() host: HTMLElement;

  componentDidLoad() {
    this.setStepNumbers();
  }

  private rerenderOnSlotChange = () => {
    this.setStepNumbers();
  };

  private setStepNumbers() {
    let number = 1;
    const steps = this.host.querySelectorAll('groupui-step, groupui-step-vertical');
    steps.forEach((groupuiStep: HTMLGroupuiStepElement | HTMLGroupuiStepVerticalElement) => {
      groupuiStep.number = number;
      groupuiStep.classList.add('step-vertical');
      number++;
    });
  }

  render() {
    return (
      <Host>
        <div id="stepper-steps" role="list" aria-label="progress">
          <slot onSlotchange={this.rerenderOnSlotChange}> </slot>
        </div>
      </Host>
    );
  }
}
